/* =================================
------------------------------------
  Cassi | Photo Studio HTML Template
  Version: 1.0
 ------------------------------------
 ====================================*/

/*----------------------------------------*/

/* Template default CSS
/*----------------------------------------*/

@import url("https://fonts.googleapis.com/css?family=Poppins:300,300i,400,400i,500,500i,600,600i,700,700i&display=swap");
@import url("https://fonts.googleapis.com/css?family=Roboto:400,400i,700&display=swap");
html, body {
  height: 100%;
  font-family: "Poppins", sans-serif;
  -webkit-font-smoothing: antialiased;
  background: #151515;
}
h1, h2, h3, h4, h5, h6 {
  margin: 0;
  color: #333333;
  font-weight: 600;
}
h1 {
  font-size: 70px;
}
h2 {
  font-size: 36px;
}
h3 {
  font-size: 30px;
}
h4 {
  font-size: 24px;
}
h5 {
  font-size: 18px;
}
h6 {
  font-size: 16px;
}
p {
  font-size: 15px;
  color: #bfbfbf;
  line-height: 1.8;
}
img {
  max-width: 100%;
}
input:focus, select:focus, button:focus, textarea:focus {
  outline: none;
}
a:hover, a:focus {
  text-decoration: none;
  outline: none;
}
ul, ol {
  padding: 0;
  margin: 0;
}
@media (min-width: 1200px) {
  .container {
    max-width: 1200px;
  }
}
/*---------------------
   Helper CSS
 -----------------------*/

.section-title {
  text-align: center;
  margin-bottom: 55px;
}
.section-title img {
  margin-bottom: 15px;
}
.section-title h2 {
  font-weight: 400;
  font-size: 38px;
  text-transform: uppercase;
}
.section-title p {
  padding-top: 15px;
  margin-bottom: 0;
}
.set-bg {
  background-repeat: no-repeat;
  background-size: cover;
  background-position: top center;
}
.spad {
  padding-top: 110px;
  padding-bottom: 105px;
}
.text-white h1, .text-white h2, .text-white h3, .text-white h4, .text-white h5, .text-white h6, .text-white p, .text-white span, .text-white li, .text-white a {
  color: #fff;
}
/*---------------------
  Commom elements
-----------------------*/

.site-btn {
  display: inline-block;
  font-size: 16px;
  padding: 17px 25px;
  min-width: 170px;
  color: #fff;
  background: #242deb;
  line-height: 1;
  letter-spacing: 1px;
  text-transform: uppercase;
  text-align: center;
  font-weight: 500;
  border: none;
  border-radius: 2px;
}
.site-btn i {
  font-size: 24px;
  position: relative;
  top: 5px;
  margin-left: 4px;
}
.site-btn:hover {
  color: #fff;
}
/* Preloder */

#preloder {
  position: fixed;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  z-index: 999999;
  background: #000;
}
.loader {
  width: 40px;
  height: 40px;
  position: absolute;
  top: 50%;
  left: 50%;
  margin-top: -13px;
  margin-left: -13px;
  border-radius: 60px;
  animation: loader 0.8s linear infinite;
  -webkit-animation: loader 0.8s linear infinite;
}
@keyframes loader {
  0% {
    -webkit-transform: rotate(0deg);
    transform: rotate(0deg);
    border: 4px solid #f44336;
    border-left-color: transparent;
  }
  50% {
    -webkit-transform: rotate(180deg);
    transform: rotate(180deg);
    border: 4px solid #673ab7;
    border-left-color: transparent;
  }
  100% {
    -webkit-transform: rotate(360deg);
    transform: rotate(360deg);
    border: 4px solid #f44336;
    border-left-color: transparent;
  }
}
@-webkit-keyframes loader {
  0% {
    -webkit-transform: rotate(0deg);
    border: 4px solid #f44336;
    border-left-color: transparent;
  }
  50% {
    -webkit-transform: rotate(180deg);
    border: 4px solid #673ab7;
    border-left-color: transparent;
  }
  100% {
    -webkit-transform: rotate(360deg);
    border: 4px solid #f44336;
    border-left-color: transparent;
  }
}
.offcanvas-menu-wrapper {
  display: none;
  position: fixed;
  width: 100%;
  height: 100%;
  left: 0;
  top: 0;
  background: #151515;
  z-index: 9999;
  align-items: center;
  justify-content: center;
}
.offcanvas-menu-wrapper .menu-switch {
  position: relative;
  top: 50px;
  opacity: 0;
  filter: alpha(opacity=0);
}
.menu-header {
  position: absolute;
  width: 100%;
  top: 0;
  left: 0;
  padding: 24px 35px 14px 40px;
}
.main-menu {
  list-style: none;
  display: inline-block;
  text-align: center;
}
.main-menu li {
  display: block;
  margin-bottom: 15px;
  position: relative;
  top: 50px;
  opacity: 0;
  filter: alpha(opacity=0);
}
.main-menu li:nth-child(5) {
  -webkit-transition: all 0.5s ease 0s;
  -moz-transition: all 0.5s ease 0s;
  -o-transition: all 0.5s ease 0s;
  transition: all 0.5s ease 0s;
}
.main-menu li:nth-child(4) {
  -webkit-transition: all 0.5s ease 0.2s;
  -moz-transition: all 0.5s ease 0.2s;
  -o-transition: all 0.5s ease 0.2s;
  transition: all 0.5s ease 0.2s;
}
.main-menu li:nth-child(3) {
  -webkit-transition: all 0.5s ease 0.4s;
  -moz-transition: all 0.5s ease 0.4s;
  -o-transition: all 0.5s ease 0.4s;
  transition: all 0.5s ease 0.4s;
}
.main-menu li:nth-child(2) {
  -webkit-transition: all 0.5s ease 0.6s;
  -moz-transition: all 0.5s ease 0.6s;
  -o-transition: all 0.5s ease 0.6s;
  transition: all 0.5s ease 0.6s;
}
.main-menu li:nth-child(1) {
  -webkit-transition: all 0.5s ease 0.8s;
  -moz-transition: all 0.5s ease 0.8s;
  -o-transition: all 0.5s ease 0.8s;
  transition: all 0.5s ease 0.8s;
}
.main-menu li:last-child {
  margin-bottom: 0;
}
.main-menu li a {
  font-size: 48px;
  font-weight: 700;
  color: #fff;
  font-family: "Roboto", sans-serif;
  transition: all 0.3s;
}
@media (max-width: 576px) {
  .main-menu li a {
    font-size: 30px;
  }
}
.main-menu li a:hover, .main-menu li a.active {
  color: #242deb;
}
.menu-footer {
  padding: 26px 40px 22px;
  position: absolute;
  width: 100%;
  left: 0;
  bottom: 0;
}
@media only screen and (min-width: 576px) and (max-width: 767px), (max-width: 576px) {
  .menu-footer {
    display: none;
  }
}
.active .menu-switch {
  top: 0;
  opacity: 1;
  filter: alpha(opacity=100);
  -webkit-transition: all 0.5s ease 0.2s;
  -moz-transition: all 0.5s ease 0.2s;
  -o-transition: all 0.5s ease 0.2s;
  transition: all 0.5s ease 0.2s;
}
.active .main-menu li {
  top: 0;
  opacity: 1;
  filter: alpha(opacity=100);
}
.active .main-menu li:nth-child(1) {
  -webkit-transition: all 0.5s ease 0s;
  -moz-transition: all 0.5s ease 0s;
  -o-transition: all 0.5s ease 0s;
  transition: all 0.5s ease 0s;
}
.active .main-menu li:nth-child(2) {
  -webkit-transition: all 0.5s ease 0.2s;
  -moz-transition: all 0.5s ease 0.2s;
  -o-transition: all 0.5s ease 0.2s;
  transition: all 0.5s ease 0.2s;
}
.active .main-menu li:nth-child(3) {
  -webkit-transition: all 0.5s ease 0.4s;
  -moz-transition: all 0.5s ease 0.4s;
  -o-transition: all 0.5s ease 0.4s;
  transition: all 0.5s ease 0.4s;
}
.active .main-menu li:nth-child(4) {
  -webkit-transition: all 0.5s ease 0.6s;
  -moz-transition: all 0.5s ease 0.6s;
  -o-transition: all 0.5s ease 0.6s;
  transition: all 0.5s ease 0.6s;
}
.active .main-menu li:nth-child(5) {
  -webkit-transition: all 0.5s ease 0.8s;
  -moz-transition: all 0.5s ease 0.8s;
  -o-transition: all 0.5s ease 0.8s;
  transition: all 0.5s ease 0.8s;
}
/*---------------------
   Header section
 -----------------------*/

.header-section {
  padding: 24px 35px 14px 40px;
  overflow: hidden;
}
.site-logo {
  display: inline-block;
  padding-top: 5px;
}
.menu-switch {
  float: right;
  cursor: pointer;
}
.menu-switch i {
  color: #fff;
  font-size: 37px;
  line-height: 37px;
}
/*---------------------
   Hero section
 -----------------------*/

@media only screen and (min-width: 768px) and (max-width: 991px) {
  .hero-section {
    padding: 0 40px;
  }
}
.hero-slider .owl-nav {
  position: absolute;
  right: 30px;
  bottom: 30px;
}
@media only screen and (min-width: 576px) and (max-width: 767px), (max-width: 576px) {
  .hero-slider .owl-nav {
    right: calc(50% - 51px);
    bottom: 50px;
  }
}
.hero-slider .owl-nav button.owl-prev, .hero-slider .owl-nav button.owl-next {
  display: inline-block;
  width: 46px;
  height: 46px;
  border: 1px solid #fff;
  color: #fff;
  font-size: 20px;
  padding-top: 6px !important;
  border-radius: 1px;
  -webkit-transition: all 0.4s;
  -moz-transition: all 0.4s;
  -o-transition: all 0.4s;
  transition: all 0.4s;
}
.hero-slider .owl-nav button.owl-prev:hover, .hero-slider .owl-nav button.owl-next:hover {
  background: #242deb;
  border-color: #242deb;
}
.hero-slider .owl-nav button.owl-prev {
  margin-right: 10px;
}
.hero-item {
  position: relative;
  display: flex;
  align-items: center;
}
.hero-text {
  position: relative;
  padding-left: 80px;
  max-width: 595px;
  z-index: 5;
}
@media only screen and (min-width: 576px) and (max-width: 767px), (max-width: 576px) {
  .hero-text {
    padding: 100px 20px 150px;
    text-align: center;
    margin: 0 auto;
  }
}
.hero-text .ht-cata {
  display: inline-block;
  padding: 5px 18px 4px;
  margin-bottom: 20px;
  font-weight: 500;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: #fff;
  background: #242deb;
  position: relative;
  opacity: 0;
  filter: alpha(opacity=0);
  top: 50px;
}
.hero-text h2 {
  font-size: 80px;
  color: #fff;
  margin-bottom: 30px;
  position: relative;
  opacity: 0;
  filter: alpha(opacity=0);
  top: 50px;
}
@media only screen and (min-width: 576px) and (max-width: 767px) {
  .hero-text h2 {
    font-size: 60px;
  }
}
@media (max-width: 576px) {
  .hero-text h2 {
    font-size: 40px;
  }
}
.hero-text p {
  font-size: 18px;
  margin-bottom: 35px;
  position: relative;
  opacity: 0;
  filter: alpha(opacity=0);
  top: 50px;
}
.hero-text .ht-btn {
  color: #fff;
  font-size: 16px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1px;
  position: relative;
  opacity: 0;
  filter: alpha(opacity=0);
  top: 50px;
}
.hero-text .ht-btn i {
  font-size: 24px;
  position: relative;
  top: 5px;
  color: #242deb;
  margin-left: 5px;
}
.hi-bg {
  position: absolute;
  height: 100%;
  width: calc(100% - 650px);
  top: 0;
  right: 0;
}
@media only screen and (min-width: 768px) and (max-width: 991px), only screen and (min-width: 576px) and (max-width: 767px), (max-width: 576px) {
  .hi-bg {
    width: 100%;
    right: auto;
    left: 0;
  }
  .hi-bg:after {
    position: absolute;
    content: "";
    width: 100%;
    height: 100%;
    left: 0;
    top: 0;
    background: #000;
    opacity: 0.8;
    filter: alpha(opacity=80);
  }
}
.owl-item.active .hero-text h2, .owl-item.active .hero-text p, .owl-item.active .hero-text .ht-cata, .owl-item.active .hero-text .ht-btn {
  top: 0;
  opacity: 1;
  filter: alpha(opacity=100);
}
.owl-item.active .hero-text .ht-cata {
  -webkit-transition: all 0.5s ease 0.4s;
  -moz-transition: all 0.5s ease 0.4s;
  -o-transition: all 0.5s ease 0.4s;
  transition: all 0.5s ease 0.4s;
}
.owl-item.active .hero-text h2 {
  -webkit-transition: all 0.5s ease 0.6s;
  -moz-transition: all 0.5s ease 0.6s;
  -o-transition: all 0.5s ease 0.6s;
  transition: all 0.5s ease 0.6s;
}
.owl-item.active .hero-text p {
  -webkit-transition: all 0.5s ease 0.8s;
  -moz-transition: all 0.5s ease 0.8s;
  -o-transition: all 0.5s ease 0.8s;
  transition: all 0.5s ease 0.8s;
}
.owl-item.active .hero-text .ht-btn {
  -webkit-transition: all 0.5s ease 1s;
  -moz-transition: all 0.5s ease 1s;
  -o-transition: all 0.5s ease 1s;
  transition: all 0.5s ease 1s;
}
/*---------------------
   Footer section
 -----------------------*/

.footer-section {
  padding: 26px 40px 22px;
