    position: relative;
    overflow: hidden;
    img {
        min-width: 100%;
    }
    &:hover {
        .team-meta {
            height: 100%;
            background: rgba(19, 29, 220, 0.7);
            h5,p {
                color: #fff;
            }
        }
        .tm-social {
            position: relative;
            visibility: visible;
            padding-top: 30px;
            @include opacity(1);
        }
    }
}
 .team-meta {
     position: absolute;
     left: 0;
     bottom: 0;
     width: 100%;
     height: 100px;
     padding: 27px 0 26px;
     text-align: center;
     display: flex;
     align-items: center;
     justify-content: center;
     background: rgba(255, 255, 255, 0.9);
     transition: all 0.4s;
     h5 {
         font-weight: 600;
         margin-bottom: 5px;
     }
     p{
         font-size: 12px;
         margin-bottom: 0;
     }
     .tm-social {
         padding-top: 0;
         visibility: hidden;
         position: absolute;
