Templates/template2/sass/_default.scss.content:
/*----------------------------------------*/
/* Template default CSS
/*----------------------------------------*/

// Google Font load
@import url('https://fonts.googleapis.com/css?family=Poppins:300,300i,400,400i,500,500i,600,600i,700,700i&display=swap');
@import url('https://fonts.googleapis.com/css?family=Roboto:400,400i,700&display=swap');

 html,
 body {
   height: 100%;
   font-family: $font_1;
   -webkit-font-smoothing: antialiased;
   background: $bg_1;
 }
 
 h1,
 h2,
 h3,
 h4,
 h5,
 h6 {
   margin: 0;
   color: $heading_color;
   font-weight: 600;
 }
 
 h1 {
   font-size: 70px;
 }
 
 h2 {
   font-size: 36px;
 }
 
 h3 {
   font-size: 30px;
 }
 
 h4 {
   font-size: 24px;
 }
 
 h5 {
   font-size: 18px;
 }
 
 h6 {
   font-size: 16px;
 }
 
 p {
   font-size: 15px;
   color: $p_color;
   line-height: 1.8;
 }
 
 img {
   max-width: 100%;
 }
 
 input,
 select,
 button,
 textarea {
   &:focus {
     outline: none;
   }
 }
 
 a:hover,
 a:focus {
   text-decoration: none;
   outline: none;
 }
 
 ul,
 ol {
   padding: 0;
   margin: 0;
 }

 @media (min-width: 1200px) {
  .container {
    max-width: 1200px;
  }
 }

Templates/template2/sass/_footer.scss.content:
/*---------------------
   Footer section
 -----------------------*/
 .footer-section {
   padding: 26px 40px 22px;
   overflow: hidden;
   @media #{$large_mobile,$small_mobile} {
    text-align: center;
  }
 }
 .footer-social {
   display: inline-block;
   a {
     display: inline-block;
     font-size: 14px;
     color: $white_color;
     margin-right: 24px;
     padding-bottom: 7px;
     position: relative;
     @include transition(all 0.4s);
     border-bottom: 2px solid rgba(255, 255, 255, 0.2);
     &:last-child {
       margin-right: 0;
     }
     &:after {
       position: absolute;
       content: "";
       width: 0;
       height: 2px;
       left: 0;
       bottom: -2px;
