Templates/template2/sass/_hero.scss.content:
/*---------------------
   Hero section
 -----------------------*/
 .hero-section {
    @media #{$tab_device} {
        padding: 0 40px;
    }
 }
 .hero-slider {
    .owl-nav {
        position: absolute;
        right: 30px;
        bottom: 30px;
        @media #{$large_mobile,$small_mobile} {
            right: calc(50% - 51px);
            bottom: 50px;
        }
        button.owl-prev,
        button.owl-next{
            display: inline-block;
            width: 46px;
            height: 46px;
            border: 1px solid #fff;
            color: #fff;
            font-size: 20px;
            padding-top: 6px !important;
            border-radius: 1px;
            @include transition(all 0.4s);
            &:hover {
                background: $primary_color;
                border-color: $primary_color;
            }
        }
        button.owl-prev{
            margin-right: 10px;
        }
    }
 }
 .hero-item {
     position: relative;
     display: flex;
     align-items: center;
     
}
 .hero-text {
     position: relative;
     padding-left: 80px;
     max-width: 595px;
     z-index: 5;
     @media #{$large_mobile,$small_mobile} {
        padding: 100px 20px 150px;
        text-align: center;
        margin: 0 auto;
    }
     .ht-cata {
         display: inline-block;
         padding: 5px 18px 4px;
         margin-bottom: 20px;
         font-weight: 500;
         font-size: 14px;
         text-transform: uppercase;
         letter-spacing: 2px;
         color: $white_color;
         background: $primary_color;
         position: relative;
         @include opacity(0);
         top: 50px;
     }
     h2 {
         font-size: 80px;
         color: $white_color;
         margin-bottom: 30px;
         position: relative;
         @include opacity(0);
         top: 50px;
         @media #{$large_mobile} {
            font-size: 60px;
        }
        @media #{$small_mobile} {
            font-size: 40px;
        }
     }
     p {
         font-size: 18px;
         margin-bottom: 35px;
         position: relative;
         @include opacity(0);
         top: 50px;
     }
     .ht-btn {
         color: $white_color;
         font-size: 16px;
         font-weight: 500;
         text-transform: uppercase;
         letter-spacing: 1px;
         position: relative;
         @include opacity(0);
         top: 50px;
         i {
             font-size: 24px;
             position: relative;
             top: 5px;
             color: $primary_color;
             margin-left: 5px;
