 .hi-bg {
    position: absolute;
    height: 100%;
    width: calc(100% - 650px);
    top: 0;
    right: 0;
    @media #{$tab_device,$large_mobile,$small_mobile} {
        width: 100%;
        right: auto;
        left: 0;
        &:after {
            position: absolute;
            content: "";
            width: 100%;
            height: 100%;
