            top: 0;
            background: #000;
            @include opacity(0.8);
        }
    }
 }

 .owl-item.active .hero-text {
    h2,p,.ht-cata,.ht-btn {
      top: 0;
      @include opacity(1);
    }
    .ht-cata {
      @include transition(all 0.5s ease 0.4s);
    }
    h2 {
      @include transition(all 0.5s ease 0.6s);
    }
    p {
      @include transition(all 0.5s ease 0.8s);
    }
    .ht-btn {
      @include transition(all 0.5s ease 1s);
    }
}

Templates/template2/sass/_loader.scss.content:
/* Preloder */
 #preloder {
    position: fixed;
    width: 100%;
    height: 100%;
    top: 0;
    left: 0;
    z-index: 999999;
    background: #000;
}

.loader {
    width: 40px;
    height: 40px;
    position: absolute;
    top: 50%;
    left: 50%;
    margin-top: -13px;
    margin-left: -13px;
    border-radius: 60px;
    animation: loader 0.8s linear infinite;
    -webkit-animation: loader 0.8s linear infinite;
}

@keyframes loader {
    0% {
        -webkit-transform: rotate(0deg);
        transform: rotate(0deg);
        border: 4px solid #f44336;
        border-left-color: transparent;
    }
    50% {
        -webkit-transform: rotate(180deg);
        transform: rotate(180deg);
        border: 4px solid #673ab7;
        border-left-color: transparent;
    }
    100% {
        -webkit-transform: rotate(360deg);
        transform: rotate(360deg);
        border: 4px solid #f44336;
        border-left-color: transparent;
    }
}

@-webkit-keyframes loader {
    0% {
        -webkit-transform: rotate(0deg);
        border: 4px solid #f44336;
        border-left-color: transparent;
    }
    50% {
        -webkit-transform: rotate(180deg);
        border: 4px solid #673ab7;
        border-left-color: transparent;
    }
    100% {
        -webkit-transform: rotate(360deg);
        border: 4px solid #f44336;
        border-left-color: transparent;
    }
}

Templates/template2/sass/_menu.scss.content:
.offcanvas-menu-wrapper {
    display: none;
    position: fixed;
    width: 100%;
    height: 100%;
    left: 0;
    top: 0;
    background: $bg_1;
    z-index: 9999;
    align-items: center;
    justify-content: center;
    .menu-switch {
        position: relative;
        top: 50px;
        @include opacity(0);
    }
}

.menu-header {
    position: absolute;
    width: 100%;
    top: 0;
    left: 0;
    padding: 24px 35px 14px 40px;
}

.main-menu {
    list-style: none;
    display: inline-block;
    text-align: center;
    li {
        display: block;
        margin-bottom: 15px;
        position: relative;
        top: 50px;
        @include opacity(0);
        &:nth-child(5) {
            @include transition(all 0.5s ease 0s);
        }
        &:nth-child(4) {
            @include transition(all 0.5s ease 0.2s);
        }
        &:nth-child(3) {
            @include transition(all 0.5s ease 0.4s);
        }
        &:nth-child(2) {
            @include transition(all 0.5s ease 0.6s);
        }
        &:nth-child(1) {
            @include transition(all 0.5s ease 0.8s);
        }
        &:last-child {
            margin-bottom: 0;
        }
        a {
            font-size: 48px;
            font-weight: 700;
            color: $white_color;
            font-family: $font_2;
            transition: all 0.3s;
            @media #{$small_mobile} {
                font-size: 30px;
            }
            &:hover,
            &.active {
                color: $primary_color;
            }
        }
    }
}

.menu-footer {
    padding: 26px 40px 22px;
    position: absolute;
    width: 100%;
    left: 0;
    bottom: 0;
    @media #{$large_mobile,$small_mobile} {
        display: none;
    }
}

.active {
    .menu-switch {
        top: 0;
        @include opacity(1);
        @include transition(all 0.5s ease 0.2s);
    }
    .main-menu {
        li {
            top: 0;
            @include opacity(1);
            &:nth-child(1) {
                @include transition(all 0.5s ease 0s);
            }
            &:nth-child(2) {
                @include transition(all 0.5s ease 0.2s);
            }
            &:nth-child(3) {
                @include transition(all 0.5s ease 0.4s);
            }
            &:nth-child(4) {
                @include transition(all 0.5s ease 0.6s);
            }
            &:nth-child(5) {
                @include transition(all 0.5s ease 0.8s);
            }
        }
    }
}

