  opacity: 0;
}

.nodisplayMain {
  display: none;
}

#nodisplayMain {
  animation: fadeaway 2s ease-in forwards;
}

@keyframes monitorIn {
  from {
    transform: translateY(-30px);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}

@keyframes chatblips {
  /* taken from http://angrytools.com/css/animation/ for bounce-in animation*/
  0% {
    opacity: 0;
    transform: scale(.3);
