  50% {
    opacity: 1;
    transform: scale(1.0);
  }
  70% {
    transform: scale(0.9);
  }
  100% {
    transform: scale(1);
    opacity: 1;
  }
}

@keyframes fadeaway {
  /* taken from http://angrytools.com/css/animation/ for bounce-in animation*/
  from {
    transform: translateY(0);
    opacity: 0;
  }
  to {
    transform: translateY(20px);
    opacity: 1;
  }

