    let gameId = 0;
    do {
      await this.networkService.getQueueData({id: id}).then((data: any) => {
        console.log(data);
        this.cooldown = data.queue.launch;
        gameId = data.queue.gameId;
        if (this.cooldown < 15)
          this.load = false;
      }).catch((error) => {
