      });
      if (this.cooldown == 15)
          await this.sleep(1000);
    } while (this.cooldown == 15)
    while (this.cooldown > 0) {
      await this.sleep(1000);
      this.cooldown -= 1;
    }
    this.launchGame(gameId);
  }

